// Définition de la broche analogique utilisée
#include <rgb_lcd.h>

const int brocheAnalogique = A0;
rgb_lcd LCD;

void setup() {
  // Initialisation de la communication série à 9600 bauds
  Serial.begin(9600);
  LCD.begin(16,2);  
}

void loop() {
  // 1. Lecture de la valeur brute (entre 0 et 1023)
  int valeurBrute = analogRead(brocheAnalogique);

  // 2. Conversion de la valeur brute en tension (0.0V à 5.0V)
  // Le CAN (Convertisseur Analogique-Numérique) de l'Arduino Uno a une résolution de 10 bits (2^10 = 1024 valeurs)
  float tension = valeurBrute * (5.0 / 1023.0);

  // 3. Affichage des résultats dans le Moniteur Série
  Serial.print("Valeur brute (0-1023) : ");
  Serial.print(valeurBrute);
  Serial.print("  |  Tension : ");
  LCD.setCursor(5,0);
  Serial.print(tension);
  LCD.print(tension);
  LCD.print(" V");
  Serial.println(" V");

  // Pause de 500 millisecondes entre chaque mesure pour faciliter la lecture
  delay(500);
}

