const int brocheAnalogique = A0;
rgb_lcd LCD;

void setup() {

  Serial.begin(9600);
  LCD.begin(16,2);  
}

void loop() {

  int valeurBrute = analogRead(brocheAnalogique);



  float tension = valeurBrute * (5.0 / 1023.0);


  Serial.print("Valeur brute (0-1023) : ");
  Serial.print(valeurBrute);
  Serial.print("  |  Tension : ");
  LCD.setCursor(0,0);
  Serial.print(tension);
  LCD.print(tension);
  LCD.print(" V");
  Serial.println(" V");


  delay(500);
}
